import {variantId,variantsFor,hasDimensions,materialFor,dimensions,categoryLabel} from './catalog-store.js?v=catalogs4';
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!=null)e.textContent=text;return e;};
const safeURL=url=>typeof url==='string'&&/^\/?(?:assets\/private-catalogs\/|private-catalogs\/)/.test(url)&&!url.includes('..')?url:null;
export function mountCatalogUI(store,{addProduct,announce}){
 let catalog=null,product=null,variant=null,limit=36,serial=0,editId=null;const $=s=>document.querySelector(s),manufacturer=$('#manufacturer-select'),select=$('#manufacturer-catalog'),category=$('#manufacturer-category'),search=$('#manufacturer-search'),grid=$('#manufacturer-products'),details=$('#catalog-detail');
 const option=(value,label)=>{const o=el('option','',label);o.value=value;return o;};
 function clearDetail(){editId=null;product=null;variant=null;details.hidden=true;}
 function chooseManufacturer(){const items=store.catalogs.filter(c=>(c.manufacturer||c.brand)===manufacturer.value);select.replaceChildren(...items.map(c=>option(c.code,c.code+' · '+c.name)));load();}
 async function load(){$('#manufacturer-results').hidden=false;const run=++serial;search.value='';search.disabled=true;clearDetail();grid.replaceChildren(el('p','fine-print','Opening catalog…'));$('#catalog-coverage').textContent='';try{const next=await store.load(select.value);if(run!==serial)return;catalog=next;catalog.products.sort((a,b)=>Number(hasDimensions(b)&&!b.placementBlocked)-Number(hasDimensions(a)&&!a.placementBlocked));category.replaceChildren(option('all','All categories'),...[...new Set(catalog.products.map(categoryLabel))].sort().map(c=>option(c,c)));search.disabled=false;limit=36;const notes=[...(Array.isArray(catalog.coverage?.notes)?catalog.coverage.notes:[]),...(Array.isArray(catalog.notes)?catalog.notes:[])];$('#catalog-coverage').textContent=notes.map(n=>typeof n==='string'?n:JSON.stringify(n)).join(' ');$('#catalog-documents').replaceChildren(...(catalog.specs||[]).filter(s=>safeURL(s.url)).map((s,n)=>{const a=el('a','spec-link',s.name||s.title||'Specification guide '+(n+1));a.href=s.url;a.target='_blank';a.rel='noopener';return a}));render();return catalog;}catch(e){search.disabled=false;grid.replaceChildren(el('p','fine-print',e.message));}}
 function render(){if(!catalog)return;const q=search.value.toLowerCase().trim(),filtered=catalog.products.filter(p=>(category.value==='all'||categoryLabel(p)===category.value)&&[p.sku,p.name,p.category].join(' ').toLowerCase().includes(q));$('#catalog-result-count').textContent=filtered.length.toLocaleString()+' records';grid.replaceChildren(...filtered.slice(0,limit).map(p=>{const b=el('button','product-row');b.type='button';const imgURL=safeURL(p.image||p.imageUrl||p.thumbnail);if(imgURL){const img=el('img');img.src=imgURL;img.alt='';img.loading='lazy';b.append(img)}const body=el('span','product-row-copy');if(p.placementBlocked||catalog.placementBlocked||!hasDimensions(p))body.append(el('span','catalog-reference-badge','Reference · verification needed'));body.append(el('strong','',p.sku||p.id),el('span','',p.name||p.description));const d=dimensions(p);body.append(el('small','',hasDimensions(p)?[d.width,d.height,d.depth].join(' × ')+' in':'See product specifications'));b.append(body,el('span','product-arrow','›'));b.onclick=()=>show(p);return b}));if(!filtered.length)grid.append(el('p','fine-print',catalog.products.length?'No matching products.':'This catalog has no verified product export yet. Use the source guides below.'));$('#catalog-more').hidden=filtered.length<=limit;}
 function show(p,chosen=null,target=null){editId=target;product=p;variant=chosen||variantsFor(catalog,p)[0]||null;details.hidden=false;details.replaceChildren();const back=el('button','text-button','‹ Back to catalog');back.onclick=()=>{details.hidden=true;$('#manufacturer-results').hidden=false};details.append(back,el('p','eyebrow',catalog.code),el('h2','',p.sku||p.id),el('p','product-description',p.name||p.description));
 const variants=variantsFor(catalog,p);if(variants.length){const label=el('label','field-label','Style & finish');label.htmlFor='catalog-variant';const v=el('select');v.id='catalog-variant';v.replaceChildren(...variants.map(entry=>option(variantId(entry),materialFor(catalog,p,entry).label)));v.value=variantId(variant);v.onchange=()=>{variant=variants.find(entry=>variantId(entry)===v.value);refreshSelection()};details.append(label,v);}
 details.append(el('div','catalog-material-preview'));const dims=el('p','dimension-summary');details.append(dims);
 const add=el('button','button primary full-width',editId?'Update selected cabinet':'Add to room');add.id='add-catalog-product';add.onclick=()=>addProduct(catalog,product,variant,editId);details.append(add);
 const help=el('p','fine-print');help.id='catalog-product-note';details.append(help);
 const spec=el('details','product-specifications');spec.append(el('summary','','Specifications & source'));const dl=el('dl');const rows=[['Manufacturer',catalog.manufacturer],['Catalog',catalog.code],['Product',p.sku],['Description',p.name],['Category',categoryLabel(p)],['Cabinet height basis',p.heightBasis],['Adjustable feet',p.adjustableFeetIn?JSON.stringify(p.adjustableFeetIn)+' inches':null],['Record status',p.availabilityStatus||p.verificationStatus||p.status],['Dimension source',typeof p.dimensionsSource==='string'?p.dimensionsSource:JSON.stringify(p.dimensionsSource||{})]];for(const [k,v] of Object.entries(p.specifications||p.specs||{}))rows.push([k,typeof v==='object'?JSON.stringify(v):v]);for(const [label,value] of rows){if(!value)continue;dl.append(el('dt','',label),el('dd','',String(value)))}spec.append(dl);details.append(spec);
 if(p.variantAvailability)details.append(el('p','fine-print','Style and finish combinations are catalog-wide references; availability for this SKU requires supplier confirmation.'));if(p.heightBasis==='cabinet-body-before-feet')details.append(el('p','fine-print','Height shown is the cabinet body only, before adjustable feet. Use Elevation for placement; installation height must include the selected feet.'));const sourceURL=safeURL(p.dimensionsSource?.url||p.source?.url);if(sourceURL){const a=el('a','spec-link','Open source specification page');a.href=sourceURL;a.target='_blank';a.rel='noopener';details.append(a)}
 const notes=Array.isArray(p.notes)?p.notes:[p.notes];for(const n of notes)if(n)details.append(el('p','fine-print',String(n)));
 $('#manufacturer-results').hidden=true;refreshSelection();details.scrollIntoView({block:'start'});
 }
 function refreshSelection(){const display=materialFor(catalog,product,variant),preview=details.querySelector('.catalog-material-preview');preview.replaceChildren();const url=safeURL(display.previewImage||display.finishImage);if(url){const img=el('img');img.src=url;img.alt=display.label;preview.append(img)}preview.append(el('span','',display.label));const d=dimensions(product,variant),canPlace=hasDimensions(product,variant)&&!product.placementBlocked&&!catalog.placementBlocked;details.querySelector('.dimension-summary').textContent=hasDimensions(product,variant)?`${d.width}″ W · ${d.height}″ H · ${d.depth}″ D`:'Dimensions need a verified product export';details.querySelector('#add-catalog-product').disabled=!canPlace;details.querySelector('#catalog-product-note').textContent=canPlace?((!display.finishImage&&!display.baseColorFactor)?'Exact finish texture is unavailable; a neutral preview is used. ':'')+'Uses catalog dimensions. The 3D shape is a planning representation; consult the specification guide for construction details.':'This record stays available for reference. Placement is disabled until its dimensions and catalog identity are verified.';}
 $('#catalog-more').onclick=()=>{limit+=36;render()};search.oninput=()=>{limit=36;render()};category.onchange=()=>{limit=36;render()};manufacturer.onchange=chooseManufacturer;select.onchange=()=>{$('#manufacturer-results').hidden=false;load()};
 for(const b of document.querySelectorAll('[data-library-mode]'))b.onclick=()=>{const mode=b.dataset.libraryMode;document.querySelectorAll('[data-library-mode]').forEach(btn=>btn.setAttribute('aria-pressed',btn===b));$('#manufacturer-library').hidden=mode!=='manufacturer';$('#planning-library').hidden=mode!=='planning';};
 return {async openSelection(ref,id){const record=store.catalogs.find(c=>c.code===ref.code);if(!record)return;manufacturer.value=record.manufacturer||record.brand;select.replaceChildren(...store.catalogs.filter(c=>(c.manufacturer||c.brand)===manufacturer.value).map(c=>option(c.code,c.code+' · '+c.name)));select.value=ref.code;await load();const p=catalog?.products.find(p=>String(p.id)===ref.productId);if(p)show(p,variantsFor(catalog,p).find(v=>variantId(v)===ref.variantId),id);},async init(){await store.init();const names=[...new Set(store.catalogs.map(c=>c.manufacturer||c.brand))];manufacturer.replaceChildren(...names.map(n=>option(n,n)));if(names.length)chooseManufacturer();else{grid.replaceChildren(el('p','fine-print','Private manufacturer catalogs are not available in this build. Planning items are still available.'));} }};
}
